<?php $displayName=!empty($conversation['customer_name'])?$conversation['customer_name']:(!empty($conversation['contact_name'])?$conversation['contact_name']:$conversation['wa_id']);?><div class="section-heading"><div><div class="eyebrow">WhatsApp monitorado</div><h1><?=htmlspecialchars($displayName)?></h1><p class="text-secondary mb-0"><?=htmlspecialchars($conversation['wa_id'])?> · <?=htmlspecialchars($conversation['status'])?></p></div><a class="btn btn-light" href="/whatsapp">Voltar</a></div><div class="card"><div class="card-body" style="max-height:58vh;overflow:auto"><?php foreach($messages as $m):?><div class="d-flex <?=$m['direction']==='out'?'justify-content-end':'justify-content-start'?> mb-2"><div class="p-3 rounded-3 <?=$m['direction']==='out'?'bg-primary text-white':'bg-body-tertiary'?>" style="max-width:min(78%,720px)"><div><?=nl2br(htmlspecialchars((string)$m['body']))?></div><small class="opacity-75"><?=htmlspecialchars($m['sender_type'])?> · <?=date('d/m H:i',strtotime($m['created_at']))?> · <?=htmlspecialchars($m['status'])?></small></div></div><?php endforeach;?></div><div class="card-footer"><form method="post" action="/whatsapp/conversations/<?=(int)$conversation['id']?>/reply" class="d-flex gap-2"><?=\App\Core\CSRF::field()?><textarea class="form-control" name="message" rows="2" maxlength="2000" placeholder="Escreva de forma próxima e natural…" required></textarea><button class="btn btn-primary">Enviar e assumir</button></form><?php if($conversation['status']!=='bot'):?><form method="post" action="/whatsapp/conversations/<?=(int)$conversation['id']?>/bot" class="mt-2"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-success">Devolver ao chatbot</button></form><?php endif;?></div></div>
